property.value:

//MethodCall[
  @MethodName = 'get'
  and ArgumentList[@Size = 1]
  and (
    ArgumentList/NumericLiteral[@ValueAsInt = 0]
    or
    ArgumentList/InfixExpression[@Operator = '-'][NumericLiteral[@ValueAsInt = 1]][
      MethodCall[@MethodName = 'size' or @MethodName = 'length']
    ]
  )
]


//MethodDeclaration/Block[count(*) = 1]/ReturnStatement[
  *[self::NumericLiteral or self::StringLiteral or self::BooleanLiteral or self::CharLiteral]
]


//Block[parent::MethodDeclaration][*[last()][self::ReturnStatement][not(*)]]
|
//Block[parent::ForStatement or parent::ForeachStatement or parent::WhileStatement or parent::DoStatement]
  [*[last()][self::ContinueStatement]]


//(ForStatement | ForeachStatement | WhileStatement | DoStatement)[
  let $loop := .
  return (
    count(.//BreakStatement[
      empty(ancestor::*[
        (self::ForStatement or self::ForeachStatement or self::WhileStatement or self::DoStatement
         or self::SwitchStatement)
        and not(. is $loop)
        and . >> $loop
      ])
    ])
    +
    count(.//ContinueStatement[
      empty(ancestor::*[
        (self::ForStatement or self::ForeachStatement or self::WhileStatement or self::DoStatement)
        and not(. is $loop)
        and . >> $loop
      ])
    ])
  ) > 1
]
